UPDATE crm_wecom_tag_sync_run
SET status = 'ERROR', error_masked = #{error}, finished_at = #{now}
WHERE tenant_id = #{tenantId}
  AND corp_id = #{corpId}
  AND sync_scope = #{syncScope}
  AND status = 'RUNNING'
  AND ((lease_until IS NOT NULL AND lease_until < #{now})
    OR (lease_until IS NULL AND started_at < #{legacyCutoff}))

