  tenant_id, corp_id, sync_scope, direction, trigger_source, adapter_name,
  status, started_at, lease_until, created_by
) VALUES (
  #{tenantId}, #{corpId}, #{syncScope}, #{direction}, #{triggerSource}, #{adapterName},
  'RUNNING', #{startedAt}, #{leaseUntil}, #{actorUserId}
)

