INSERT INTO crm_wecom_customer_tag_push_task (
  tenant_id, corp_id, customer_id, wecom_contact_id, wecom_userid, external_userid,
  add_tag_ids_json, remove_tag_ids_json, status, attempts, max_attempts, next_retry_at,
  trigger_source, created_by
) VALUES (
  #{tenantId}, #{corpId}, #{customerId}, #{wecomContactId}, #{wecomUserid}, #{externalUserid},
  #{addTagIdsJson}, #{removeTagIdsJson}, 'PENDING', 0, #{maxAttempts}, #{nextRetryAt},
  #{triggerSource}, #{actorUserId}
)

mapper.select:
SELECT 
FROM crm_wecom_customer_tag_push_task
WHERE tenant_id = #{tenantId} AND id = #{taskId}

SELECT 
FROM crm_wecom_customer_tag_push_task
WHERE tenant_id = #{tenantId} AND corp_id = #{corpId}

  AND status = #{status}

ORDER BY updated_at DESC, id DESC
LIMIT #{limit}

mapper.update:
UPDATE crm_wecom_customer_tag_push_task
SET status = 'PROCESSING',
    attempts = attempts + 1,
    lease_until = #{leaseUntil},
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{taskId}
  AND status IN ('PENDING', 'RETRYABLE')
  AND (next_retry_at IS NULL OR next_retry_at <= #{now})
  AND attempts = #{expectedAttempts}

UPDATE crm_wecom_customer_tag_push_task
SET status = #{status},
    next_retry_at = #{nextRetryAt},
    lease_until = NULL,
    error_masked = #{errorMasked},
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{taskId}
  AND status = 'PROCESSING'
  AND attempts = #{expectedAttempts}

UPDATE crm_wecom_contact
SET tag_snapshot_json = #{tagSnapshotJson}, version = version + 1
WHERE tenant_id = #{tenantId} AND id = #{wecomContactId}
